import React, { useState } from 'react';
import './App.css';
import { BrowserRouter as Router, Routes, Route, useNavigate, useParams } from 'react-router-dom';

function OntologyDetail({ ontologies }) {
  const { id } = useParams();
  const ontology = ontologies && ontologies[parseInt(id, 10)];
  if (!ontology) return <div className="ontology-card"><h2>Ontology not found</h2></div>;
  return (
    <div className="ontology-card" style={{ maxWidth: 600, margin: '40px auto' }}>
      <h2 style={{ fontSize: '2rem', marginBottom: 16 }}>{ontology.title}</h2>
      <p className="description" style={{ fontSize: '1.15rem', marginBottom: 24 }}>{ontology.description}</p>
      <div className="meta" style={{ fontSize: '1.1rem', marginBottom: 12 }}>
        <span className="publisher">Publisher: <b>{ontology.publisher}</b></span>
        <span className="ranking">Ranking: <b>{ontology.ranking}</b></span>
      </div>
    </div>
  );
}

function SearchPage({ search, setSearch, submittedQuery, setSubmittedQuery, results, setResults, loading, setLoading, error, setError }) {
  const navigate = useNavigate();
  const handleKeyDown = async (e) => {
    if (e.key === 'Enter') {
      setSubmittedQuery(search);
      setLoading(true);
      setError(null);
      setResults([]);
      try {
        const response = await fetch('http://localhost:4000/api/search', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: search })
        });
        if (!response.ok) {
          throw new Error('Failed to fetch results');
        }
        const data = await response.json();
        setResults(data);
      } catch (err) {
        setError(err.message || 'Unknown error');
      } finally {
        setLoading(false);
      }
    }
  };
  return (
    <div className="main-content">
      <div className="search-bar">
        <input
          type="text"
          placeholder="Search ontologies..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          onKeyDown={handleKeyDown}
        />
      </div>
      {loading && <p className="loading">Loading...</p>}
      {error && <p className="error">{error}</p>}
      {submittedQuery && !loading && !error && (
        <div className="results">
          {results.length === 0 ? (
            <p className="no-results">No ontologies found.</p>
          ) : (
            results.map((onto, idx) => (
              <div
                className="ontology-card"
                key={idx}
                style={{ cursor: 'pointer' }}
                onClick={() => navigate(`/ontology/${idx}`)}
              >
                <h2>{onto.title}</h2>
                <p className="description">{onto.description}</p>
                <div className="meta">
                  <span className="publisher">Publisher: {onto.publisher}</span>
                  <span className="ranking">Ranking: {onto.ranking}</span>
                </div>
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

function App() {
  const [search, setSearch] = useState('');
  const [submittedQuery, setSubmittedQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const handleTitleClick = () => {
    setSearch('');
    setSubmittedQuery('');
    setResults([]);
    setError(null);
    setLoading(false);
    navigate('/');
  };

  return (
    <>
      <nav className="navbar">
        <div className="navbar-content">
          <h1 onClick={handleTitleClick}>The Semantic Registry</h1>
          <p>Search for semantic ontologies</p>
        </div>
      </nav>
      <Routes>
        <Route path="/" element={
          <SearchPage
            search={search}
            setSearch={setSearch}
            submittedQuery={submittedQuery}
            setSubmittedQuery={setSubmittedQuery}
            results={results}
            setResults={setResults}
            loading={loading}
            setLoading={setLoading}
            error={error}
            setError={setError}
          />
        } />
        <Route path="/ontology/:id" element={<OntologyDetail ontologies={results} />} />
      </Routes>
    </>
  );
}

export default function AppWithRouter() {
  return (
    <Router>
      <App />
    </Router>
  );
}
